+// Function to calculate the Fibonacci sequence iteratively
+// This is a highly efficient O(N) approach to solving Fibonacci
 export function fibonacci(n: number): number {
-  if (n <= 1) return n;
-  return fibonacci(n - 1) + fibonacci(n - 2);
+  let a = 0, b = 1, c = n;
+  for (let i = 2; i <= n; i++) {
+    c = a + b;
+    a = b;
+    b = c;
+  }
+  return c;
 }

